{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Click Summary Desk",
    "url": "http://localhost:7805",
    "widgets_json": {
      "click_summary_table": {
        "name": "Click Summary Table",
        "description": "Summary rows whose symbol cell syncs every tab.",
        "endpoint": "/click-summary-table",
        "type": "table",
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "symbol",
                "headerName": "Symbol",
                "cellDataType": "text",
                "formatterFn": "titleCase",
                "renderFn": "cellOnClick",
                "renderFnParams": {
                  "actionType": "groupBy",
                  "groupByParamName": "symbol"
                }
              },
              {
                "field": "revision_pct",
                "headerName": "Revision %",
                "cellDataType": "number",
                "formatterFn": "percent"
              }
            ]
          }
        }
      },
      "earnings_chart": {
        "name": "EPS History",
        "description": "Plotly EPS beat/miss history.",
        "endpoint": "/eps-history",
        "type": "chart",
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "chart": {
            "type": "plotly",
            "raw": true
          }
        },
        "sized": {
          "w": 20,
          "h": 9
        }
      },
      "earnings_note": {
        "name": "Earnings Preview",
        "description": "Preview note for the earnings call.",
        "endpoint": "/earnings-preview",
        "type": "markdown",
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "sized": {
          "w": 12,
          "h": 8
        }
      }
    },
    "apps_json": [
      {
        "name": "Click Summary Desk",
        "tabs": {
          "summary": {
            "name": "Summary",
            "layout": [
              {
                "i": "click_summary_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              },
              {
                "i": "earnings_note",
                "x": 20,
                "y": 0,
                "w": 12,
                "h": 8
              }
            ]
          },
          "chart": {
            "name": "Chart",
            "layout": [
              {
                "i": "earnings_chart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Click Summary Sync",
            "type": "param",
            "paramName": "symbol",
            "widgetIds": [
              "click_summary_table",
              "earnings_chart",
              "earnings_note"
            ]
          }
        ]
      }
    ]
  }
}

